17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Objects;
25	import java.util.regex.Pattern;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerEmailException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
43	import org.springframework.samples.petclinic.rest.advice.OwnerDailyRegistrationLimitException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.samples.petclinic.util.AddressNormalizer;
53	import org.springframework.samples.petclinic.util.BusinessDayAdjuster;
54	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
55	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
75	     * carrying the new owner's id, customer code and registration date.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    /**
80	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
81	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
82	     * input (e.g. a value without an '@') is rejected.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
86	
87	    /**
88	     * Maximum number of owners a single city may hold. A create whose city already contains this many
89	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
90	     */
91	    private static final int MAX_OWNERS_PER_CITY = 50;
92	
93	    /**
94	     * Maximum number of owners that may be registered in a single day. A create made once this many
95	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
96	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
97	     */
98	    private static final int MAX_OWNERS_PER_DAY = 100;
99	
100	    /**
101	     * The number of owners that must already carry a given day's {@code registrationDate} before a
102	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
103	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
104	     */
105	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
106	
107	    private final ClinicService clinicService;
108	
109	    private final OwnerMapper ownerMapper;
110	
111	    private final PetMapper petMapper;
112	
113	    private final VisitMapper visitMapper;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        normalizeAddress(ownerFieldsDto);
154	        rejectBlankOwnerFields(ownerFieldsDto);
155	        normalizeTelephone(ownerFieldsDto);
156	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
157	        rejectDuplicateHousehold(ownerFieldsDto);
158	        rejectCityAtCapacity(ownerFieldsDto.getCity());
159	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
160	        long registeredThatDay = countRegisteredOn(registrationDate);
161	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
162	        normalizeEmail(ownerFieldsDto);
163	        rejectDuplicateEmail(ownerFieldsDto.getEmail());
164	        HttpHeaders headers = new HttpHeaders();
165	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
166	        owner.setRegistrationDate(registrationDate);
167	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
170	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
183	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
184	        if (currentOwner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        currentOwner.setAddress(ownerFieldsDto.getAddress());
188	        currentOwner.setCity(ownerFieldsDto.getCity());
189	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
190	        currentOwner.setLastName(ownerFieldsDto.getLastName());
191	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
192	        normalizeEmail(ownerFieldsDto);
193	        currentOwner.setEmail(ownerFieldsDto.getEmail());
194	        currentOwner.setHouseholdId(
195	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Override
250	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
251	        HttpHeaders headers = new HttpHeaders();
252	        Visit visit = visitMapper.toVisit(visitFieldsDto);
253	        Pet pet = new Pet();
254	        pet.setId(petId);
255	        visit.setPet(pet);
256	        this.clinicService.saveVisit(visit);
257	        VisitDto visitDto = visitMapper.toVisitDto(visit);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
259	            .buildAndExpand(visit.getId()).toUri());
260	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
261	    }
262	
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner != null) {
269	            Pet pet = owner.getPet(petId);
270	            if (pet != null) {
271	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
276	
277	    /**
278	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
279	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
280	     * the request body already rejects null and empty values, but permits whitespace-only strings
281	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
282	     * that gap so every required field must carry a non-blank value.
283	     *
284	     * @param ownerFieldsDto the submitted owner fields
285	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
286	     */
287	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
288	        List<String> missing = new ArrayList<>();
289	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
290	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
291	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
292	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
293	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
294	        if (!missing.isEmpty()) {
295	            throw new InvalidOwnerFieldsException(missing);
296	        }
297	    }
298	
299	    private void addIfBlank(List<String> missing, String fieldName, String value) {
300	        if (value == null || value.isBlank()) {
301	            missing.add(fieldName);
302	        }
303	    }
304	
305	    /**
306	     * Normalizes the submitted {@code address} on create to its canonical form (see
307	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
308	     * stored and returned, and the form every later address comparison (the required-field check,
309	     * household duplicate detection and the shared household id) is judged on. A null address is left
310	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
311	     * after normalization likewise reduces to the empty string and is rejected there.
312	     *
313	     * @param ownerFieldsDto the submitted owner fields
314	     */
315	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
316	        String address = ownerFieldsDto.getAddress();
317	        if (address == null) {
318	            return;
319	        }
320	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
321	    }
322	
323	    /**
324	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
325	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
326	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
327	     * {@code 400 Bad Request}.
328	     *
329	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
330	     *                       {@link #rejectBlankOwnerFields} having already run)
331	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
332	     */
333	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
334	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
335	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
336	        ownerFieldsDto.setTelephone(normalized);
337	    }
338	
339	    /**
340	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
341	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
342	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
343	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
344	     *
345	     * @param ownerFieldsDto the submitted owner fields
346	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
347	     */
348	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
349	        String email = ownerFieldsDto.getEmail();
350	        if (email == null || email.isBlank()) {
351	            return;
352	        }
353	        email = email.trim();
354	        if (!EMAIL_PATTERN.matcher(email).matches()) {
355	            throw new InvalidOwnerFieldsException(List.of("email"));
356	        }
357	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
358	    }
359	
360	    /**
361	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
362	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
363	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
364	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
365	     *
366	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
367	     *                            {@link #normalizeTelephone}
368	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
369	     */
370	    private void rejectDuplicateTelephone(String normalizedTelephone) {
371	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
372	        boolean inUse = this.clinicService.findAllOwners().stream()
373	            .map(Owner::getTelephone)
374	            .filter(Objects::nonNull)
375	            .map(TelephoneNormalizer::toComparisonKey)
376	            .anyMatch(comparisonKey::equals);
377	        if (inUse) {
378	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
379	        }
380	    }
381	
382	    /**
383	     * Rejects creating an owner whose lower-cased email is already used by any other owner. Both the
384	     * submitted email and every existing owner's stored email are compared case-insensitively (on
385	     * their lower-cased form), so equality is judged on that form alone. A match is reported as a
386	     * {@code 409 Conflict}. An absent (null or blank) email is not subject to this rule, email being
387	     * optional.
388	     *
389	     * @param normalizedEmail the submitted email, already trimmed and lower-cased by
390	     *                        {@link #normalizeEmail}, or null/blank when no email was supplied
391	     * @throws DuplicateOwnerEmailException if another owner already uses the same email
392	     */
393	    private void rejectDuplicateEmail(String normalizedEmail) {
394	        if (normalizedEmail == null || normalizedEmail.isBlank()) {
395	            return;
396	        }
397	        String comparisonKey = normalizedEmail.toLowerCase(Locale.ROOT);
398	        boolean inUse = this.clinicService.findAllOwners().stream()
399	            .map(Owner::getEmail)
400	            .filter(Objects::nonNull)
401	            .map(email -> email.toLowerCase(Locale.ROOT))
402	            .anyMatch(comparisonKey::equals);
403	        if (inUse) {
404	            throw new DuplicateOwnerEmailException(normalizedEmail);
405	        }
406	    }
407	
408	    /**
409	     * Rejects creating an owner who shares a household with any existing owner, unless the request
410	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
411	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
412	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
413	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
414	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
415	     *
416	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
417	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
418	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
419	     *                                          request did not opt in with {@code sharesHousehold}
420	     */
421	    /**
422	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
423	     * both match the submitted values, compared case-insensitively. The count reflects only owners
424	     * already persisted at the time of the create, so the owner being created is never included.
425	     *
426	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
427	     *                  having already run)
428	     * @param lastName  the submitted last name (non-blank here)
429	     * @return the number of existing owners sharing the same first and last name
430	     */
431	    private int countNamesakes(String firstName, String lastName) {
432	        return (int) this.clinicService.findAllOwners().stream()
433	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
434	                && lastName.equalsIgnoreCase(owner.getLastName()))
435	            .count();
436	    }
437	
438	    /**
439	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
440	     * whose stored {@code householdId} equals the value derived for the owner being created. The
441	     * count reflects only owners already persisted at the time of the create, so the owner being
442	     * created is never included; callers add one to obtain the household size after this create.
443	     *
444	     * @param householdId the household identifier derived for the owner being created (see
445	     *                    {@link HouseholdNormalizer#toHouseholdId})
446	     * @return the number of existing owners already sharing that household
447	     */
448	    private int countHouseholdMembers(String householdId) {
449	        if (householdId == null) {
450	            return 0;
451	        }
452	        return (int) this.clinicService.findAllOwners().stream()
453	            .map(Owner::getHouseholdId)
454	            .filter(householdId::equals)
455	            .count();
456	    }
457	
458	    /**
459	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
460	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
461	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
462	     *
463	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
464	     *             run)
465	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
466	     */
467	    private void rejectCityAtCapacity(String city) {
468	        long ownersInCity = this.clinicService.findAllOwners().stream()
469	            .map(Owner::getCity)
470	            .filter(Objects::nonNull)
471	            .filter(city::equalsIgnoreCase)
472	            .count();
473	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
474	            throw new OwnerCityAtCapacityException(city);
475	        }
476	    }
477	
478	    /**
479	     * Resolves the effective registration date for a create, rolled onto a business day. The
480	     * supplied date is used when present, otherwise the server's current date; either way the result
481	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
482	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
483	     * stored {@code registrationDate}, the membership number's year segment and the daily
484	     * create-limit's per-day count - is judged on this adjusted date.
485	     *
486	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
487	     *                                 default to the server's current date
488	     * @return the effective registration date, guaranteed to fall on a business day
489	     */
490	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
491	        LocalDate registrationDate =
492	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
493	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
494	    }
495	
496	    /**
497	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
498	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
499	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
500	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
501	     * Too Many Requests}.
502	     *
503	     * @param registrationDate   the create's effective registration date, already rolled onto a
504	     *                           business day by {@link #effectiveRegistrationDate}
505	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
506	     *                           {@code registrationDate} equals {@code registrationDate}
507	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
508	     *                                              owner registrations
509	     */
510	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
511	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
512	            throw new OwnerDailyRegistrationLimitException(registrationDate);
513	        }
514	    }
515	
516	    /**
517	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
518	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
519	     * bulk-signup warning are judged on.
520	     *
521	     * @param registrationDate the create's effective registration date, already rolled onto a business
522	     *                         day by {@link #effectiveRegistrationDate}
523	     * @return the number of existing owners registered on that day
524	     */
525	    private long countRegisteredOn(LocalDate registrationDate) {
526	        return this.clinicService.findAllOwners().stream()
527	            .map(Owner::getRegistrationDate)
528	            .filter(registrationDate::equals)
529	            .count();
530	    }
531	
532	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
533	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
534	            return;
535	        }
536	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
537	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
538	        boolean inUse = this.clinicService.findAllOwners().stream()
539	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
540	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
541	            .anyMatch(comparisonKey::equals);
542	        if (inUse) {
543	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
544	        }
545	    }
546	}
